pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint256 gap) public {
        // Roll far enough forward that blockhash(storedBlock) == 0, making the
        // answer deterministic: answer = keccak(abi.encodePacked(bytes32(0))).
        gap = bound(gap, 257, 1e9);

        bytes32 g = keccak256(abi.encodePacked(bytes32(0)));
        address a1 = address(0xA11);
        address a2 = address(0xA22);

        vm.deal(a1, 1 ether);
        vm.prank(a1);
        c.lockInGuess{value: 1 ether}(g);
        vm.deal(a2, 1 ether);
        vm.prank(a2);
        c.lockInGuess{value: 1 ether}(g);

        vm.roll(block.number + gap);

        vm.prank(a1);
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }

        // Reference: stored guess matches keccak(blockhash(0-block)) so settle succeeds.
        // Mutant: stored guess is ~g, never matches, settle always reverts.
        assertTrue(ok);
    }
}

