pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 g) public {
        vm.assume(actor != address(0));
        // the only guess that makes the reference itself attempt a payout is keccak(abi.encodePacked(bytes32(0)))
        vm.assume(g != keccak256(abi.encodePacked(bytes32(0))));

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);

        uint256 target = block.number + 1;
        vm.roll(target + 1); // target block has passed; blockhash(target) == 0, so answer == keccak(0)

        vm.prank(actor);
        try c.settle() {
            assertTrue(true, "settle should succeed for a wrong guess");
        } catch {
            assertTrue(false, "settle must not revert for a non-winning guess");
        }
    }
}

