pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }
    function testFuzz_property(bytes32 g, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        // lock in the fuzzed guess at the next block
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);
        // move past the target block; blockhash(target) resolves to 0, so the
        // answer is keccak256(bytes32(0)) regardless of the fuzzed values
        vm.roll(block.number + 2);
        vm.prank(actor);
        c.settle();
        // universal rule: the winner (guess == answer) ends with 2 ether,
        // a loser ends with their original 1 ether; the mutant's stored ~g
        // makes the true winner lose their prize for g == keccak256(bytes32(0))
        bool win = (g == keccak256(bytes32(0)));
        assertTrue(win ? actor.balance == 2 ether : actor.balance == 1 ether);
    }
}

