pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint256 seed, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        // general rule over all hashes: settlement pays 2 ether iff the locked hash
        // equals keccak256(abi.encodePacked(blockhash(targetBlock))).
        // seed == 0 selects the hash that will match (blockhash will be unavailable,
        // so answer = keccak256(abi.encodePacked(bytes32(0)))); other seeds give other hashes.
        bytes32 winningAnswer = keccak256(abi.encodePacked(bytes32(0)));
        bytes32 hash = (seed == 0) ? winningAnswer : bytes32(seed);

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);
        uint256 target = block.number; // guess.block was set to block.number + 1 at lock time

        // push far beyond 256 blocks so blockhash(target+1) is unavailable -> bytes32(0)
        vm.roll(block.number + 400);

        vm.prank(actor);
        c.settle();

        bytes32 answer = keccak256(abi.encodePacked(blockhash(target + 1)));
        bool shouldWin = (hash == answer);
        assertTrue(
            address(actor).balance == 1 ether + (shouldWin ? 2 ether : 0),
            "settlement payout must equal 2 ether iff locked hash matches blockhash answer"
        );
    }
}

