pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    bytes32 constant EMPTY_HASH = 0xc5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470;

    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(bytes32 guess, address actor) public {
        vm.assume(actor != address(0));
        // Admissible domain: a winning guess. With the target block far outside
        // the 256-block hash window, blockhash(target) == 0, so the settled
        // answer is keccak256(abi.encodePacked(bytes32(0))) == EMPTY_HASH.
        vm.assume(guess == EMPTY_HASH);

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        uint256 target = block.number; // lockInGuess stored block.number+1 before our read? no: read before is required
        // recompute properly: block.number was n during lock, stored value is n+1
        // (we roll far past both so blockhash of the stored block is 0 either way)
        vm.roll(block.number + 300);

        vm.prank(actor);
        c.settle();

        assertTrue(address(c).balance == 0 && actor.balance == 2 ether);
    }
}

