import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 skipBlocks) public {
        vm.assume(actor != address(c));
        bound(skipBlocks, 300, 10000);

        // lock in the hash that will equal the settled answer:
        // after skipping >256 blocks, blockhash(target) == bytes32(0),
        // so answer == keccak256(abi.encodePacked(bytes32(0)))
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(bytes32(0))));

        // move well past the target block so blockhash(target) is unavailable (bytes32(0))
        vm.roll(block.number + skipBlocks);

        vm.prank(actor);
        c.settle();

        // Rule: a winning guess always pays out the full 2 ether, emptying c.
        assertTrue(address(c).balance == 0);
    }
}

