contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // `candidate` ranges over any bytes32 value a user might claim as the
    // guessed hash. The rule: no matter which candidate is in play, settling
    // from an address that has NOT previously called lockInGuess must revert,
    // because the locked block is zero and no blockhash can be checked.
    // This test contract's address never locks a guess, so settle() here
    // always exercises the no-guess path.
    function run(bytes32 candidate) public {
        require(true);

        bool reverted;
        try c.settle() { reverted = false; } catch { reverted = true; }

        // For any candidate guess, settle() from a never-locked address
        // must revert (original contract), whereas the mutant lets it pass.
        assert(reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 wouldBeGuess) public payable {
        // Fresh caller: this contract never sent ether to lock a guess.
        require(address(this).balance == 0);
        require(msg.value == 0);
        // settle() is the first and only interaction with c, so the caller's
        // guess block is zero (never locked in), for any would-be guess value.
        bool reverted;
        try c.settle() { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // `salt` represents an arbitrary (never locked-in) guess seed: for ANY value of
    // `salt`, and regardless of any Ether amount, calling settle() from an address
    // that never called lockInGuess must revert.
    function run(bytes32 salt) public payable {
        require(true);
        bool reverted;
        try c.settle() { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}
